package com.bmd.scanner;

import android.content.*;
import android.content.pm.ActivityInfo;
import android.content.res.Configuration;
import android.os.SystemClock;
import android.view.*;
import android.widget.*;
import androidx.test.core.app.ActivityScenario;
import androidx.test.ext.junit.runners.AndroidJUnit4;
import androidx.test.platform.app.InstrumentationRegistry;
import androidx.test.uiautomator.*;
import java.util.Locale;
import java.util.concurrent.atomic.AtomicBoolean;
import org.junit.*;
import org.junit.runner.RunWith;
import static org.junit.Assert.*;

@RunWith(AndroidJUnit4.class)
public class ThemeIntegrationTest {
    private static android.graphics.Rect screenBounds(View view){int[] xy=new int[2];view.getLocationOnScreen(xy);return new android.graphics.Rect(xy[0],xy[1],xy[0]+view.getWidth(),xy[1]+view.getHeight());}
    private static int faceInk(View view){android.graphics.Bitmap image=android.graphics.Bitmap.createBitmap(128,96,android.graphics.Bitmap.Config.ARGB_8888);android.graphics.drawable.Drawable face=view.getBackground();android.graphics.Rect original=new android.graphics.Rect(face.getBounds());face.setBounds(0,0,128,96);face.draw(new android.graphics.Canvas(image));int result=image.getPixel(64,60);face.setBounds(original);image.recycle();return result;}
    @Before public void before()throws Exception{DeviceSupport.clear();DeviceSupport.permission();}
    @Test public void allSkinsKeepMenuStructureOriginalTransparentBrandAndPersist()throws Exception{
        for(String theme:ThemeSkin.IDS){DeviceSupport.context().getSharedPreferences("MainActivity",0).edit().putString("colourTheme",theme).putString("language","nl").commit();
            try(ActivityScenario<MainActivity> scenario=ActivityScenario.launch(MainActivity.class)){
                final android.graphics.Rect[] homeBrand={null};
                scenario.onActivity(a->{assertEquals(theme,ThemeSkin.active.id);assertEquals(ActivityInfo.SCREEN_ORIENTATION_PORTRAIT,a.getRequestedOrientation());a.showHome();android.graphics.Bitmap scanner=(android.graphics.Bitmap)DeviceSupport.get(new UiArt.ScannerMark(a),"art");assertTrue("Scanner artwork has real alpha",scanner.hasAlpha());assertEquals(0,android.graphics.Color.alpha(scanner.getPixel(0,0)));assertNotNull(DeviceSupport.tag(a.getWindow().getDecorView(),"reference-home"));});DeviceSupport.shot(scenario,"build3-theme-home-"+theme);scenario.onActivity(a->homeBrand[0]=screenBounds(DeviceSupport.tag(a.getWindow().getDecorView(),"home-brand")));
                scenario.onActivity(a->{a.chooseScan();});DeviceSupport.shot(scenario,"build3-theme-scan-menu-"+theme);
                scenario.onActivity(a->{a.showSettings();View decor=a.getWindow().getDecorView();assertNotNull(DeviceSupport.tag(decor,"language"));assertNotNull(DeviceSupport.tag(decor,"themes"));assertNotNull(DeviceSupport.tag(decor,"about"));assertNull(DeviceSupport.tag(decor,"scanner-settings"));assertNull(DeviceSupport.tag(decor,"document-settings"));View brand=DeviceSupport.tag(decor,"theme-brand");assertNotNull(brand);assertNull(brand.getBackground());assertEquals(0,brand.getElevation(),0);assertTrue(brand.getContentDescription().toString().contains(theme.equals("translumina")?"Translumina":"Blue Medical"));android.graphics.Bitmap logo=android.graphics.BitmapFactory.decodeResource(a.getResources(),com.bmd.scanner.R.drawable.blue_medical_logo),transparent=android.graphics.Bitmap.createBitmap(logo.getWidth(),logo.getHeight(),android.graphics.Bitmap.Config.ARGB_8888);try{android.graphics.Paint paint=new android.graphics.Paint(3);paint.setColorFilter(ThemeSkin.active.brandFilter());new android.graphics.Canvas(transparent).drawBitmap(logo,0,0,paint);assertEquals("Transparent outside logo",0,android.graphics.Color.alpha(transparent.getPixel(0,0)));assertEquals("White source matte must disappear",0,android.graphics.Color.alpha(transparent.getPixel(700,200)));int visible=0;for(int y=0;y<logo.getHeight();y+=3)for(int x=0;x<logo.getWidth();x+=3)if(android.graphics.Color.alpha(transparent.getPixel(x,y))>240)visible++;assertTrue("Logo lettering must remain visible",visible>1000);}finally{logo.recycle();transparent.recycle();}});DeviceSupport.shot(scenario,"build3-theme-settings-"+theme);scenario.onActivity(a->{View root=a.getWindow().getDecorView();assertEquals("Home and Settings logo position and size",homeBrand[0],screenBounds(DeviceSupport.tag(root,"theme-brand")));if(theme.equals("translumina")){int blue=faceInk(DeviceSupport.tag(root,"language")),purple=faceInk(DeviceSupport.tag(root,"themes")),orange=faceInk(DeviceSupport.tag(root,"about"));assertTrue("Language stays blue on red Translumina",android.graphics.Color.blue(blue)>android.graphics.Color.red(blue)+40);assertTrue("Themes stays purple on red Translumina",android.graphics.Color.blue(purple)>android.graphics.Color.green(purple)+40&&android.graphics.Color.red(purple)>android.graphics.Color.green(purple)+15);assertTrue("About stays amber/orange on red Translumina",android.graphics.Color.red(orange)>android.graphics.Color.blue(orange)+40);}});
                scenario.recreate();scenario.onActivity(a->{assertEquals(theme,ThemeSkin.active.id);a.themes();android.app.Dialog dialog=(android.app.Dialog)DeviceSupport.get(a,"dialog");for(String id:ThemeSkin.IDS){assertNotNull(DeviceSupport.tag(dialog.getWindow().getDecorView(),"theme-"+id));assertNotNull(DeviceSupport.tag(dialog.getWindow().getDecorView(),"theme-icon-"+id));}assertTrue(((TextView)DeviceSupport.tag(dialog.getWindow().getDecorView(),"theme-name-bmd")).getText().toString().startsWith("Blue Medical"));assertTrue(((TextView)DeviceSupport.tag(dialog.getWindow().getDecorView(),"theme-name-dark")).getText().toString().startsWith("Donker"));assertTrue(((TextView)DeviceSupport.tag(dialog.getWindow().getDecorView(),"theme-name-light")).getText().toString().startsWith("Licht"));});DeviceSupport.shot(scenario,"build3-theme-picker-"+theme);scenario.onActivity(a->((android.app.Dialog)DeviceSupport.get(a,"dialog")).dismiss());
            }
        }
    }
    @Test public void choosingAnyLanguageImmediatelyTranslatesHeadingAndApplyBeforeSaving()throws Exception{
        for(String theme:ThemeSkin.IDS){DeviceSupport.context().getSharedPreferences("MainActivity",0).edit().putString("colourTheme",theme).putString("language","nl").commit();
            try(ActivityScenario<MainActivity> scenario=ActivityScenario.launch(MainActivity.class)){
                scenario.onActivity(a->{a.showSettings();a.languages();});
                for(int n=0;n<MainActivity.LANGS.length;n++){final int index=n;scenario.onActivity(a->{android.app.Dialog d=(android.app.Dialog)DeviceSupport.get(a,"dialog");View root=d.getWindow().getDecorView();RadioGroup choices=(RadioGroup)DeviceSupport.tag(root,"language-options");choices.check(choices.getChildAt(index).getId());assertEquals(a.s("choose_language"),((TextView)DeviceSupport.tag(root,"sheet-title")).getText().toString());assertEquals(a.s("apply"),((TextView)DeviceSupport.tag(root,"language-apply")).getText().toString());assertEquals("nl",a.getSharedPreferences("MainActivity",0).getString("language",""));if(index==1)assertEquals("Apply",((TextView)DeviceSupport.tag(root,"language-apply")).getText().toString());});}
                scenario.onActivity(a->{android.app.Dialog d=(android.app.Dialog)DeviceSupport.get(a,"dialog");RadioGroup choices=(RadioGroup)DeviceSupport.tag(d.getWindow().getDecorView(),"language-options");choices.check(choices.getChildAt(1).getId());});DeviceSupport.shot(scenario,"build3-theme-english-preview-"+theme);
                scenario.onActivity(a->{android.app.Dialog d=(android.app.Dialog)DeviceSupport.get(a,"dialog");DeviceSupport.tag(d.getWindow().getDecorView(),"language-apply").performClick();assertEquals("en",a.getSharedPreferences("MainActivity",0).getString("language",""));});InstrumentationRegistry.getInstrumentation().waitForIdleSync();scenario.onActivity(a->assertTrue("Settings must rebuild in English after dismissal",DeviceSupport.hasText(a.getWindow().getDecorView(),"Themes")));scenario.onActivity(a->{a.themes();android.app.Dialog d=(android.app.Dialog)DeviceSupport.get(a,"dialog");assertTrue(((TextView)DeviceSupport.tag(d.getWindow().getDecorView(),"theme-name-dark")).getText().toString().startsWith("Dark"));assertTrue(((TextView)DeviceSupport.tag(d.getWindow().getDecorView(),"theme-name-light")).getText().toString().startsWith("Light"));d.dismiss();});
            }
        }
    }
    @Test public void nativeZoomAnimatesInEveryPaletteAndCameraAloneMayRotate()throws Exception{
        for(String theme:ThemeSkin.IDS){DeviceSupport.context().getSharedPreferences("MainActivity",0).edit().putString("colourTheme",theme).commit();DeviceSupport.context().getSharedPreferences("BoxScanActivity",0).edit().clear().commit();
            try(ActivityScenario<BoxScanActivity> scenario=ActivityScenario.launch(new Intent(DeviceSupport.context(),BoxScanActivity.class).putExtra("language","nl"))){UiDevice device=UiDevice.getInstance(InstrumentationRegistry.getInstrumentation());UiObject2 input=device.wait(Until.findObject(By.clazz(EditText.class)),5000);assertNotNull(input);input.setText("13");device.findObject(By.res("android:id/button1")).click();SystemClock.sleep(250);scenario.onActivity(a->DeviceSupport.call(a,"cameraPage",new Class<?>[]{}));long deadline=SystemClock.elapsedRealtime()+35000;AtomicBoolean ready=new AtomicBoolean();while(SystemClock.elapsedRealtime()<deadline){scenario.onActivity(a->ready.set((Boolean)DeviceSupport.get(a,"ready")));if(ready.get())break;SystemClock.sleep(150);}assertTrue("Camera must bind",ready.get());
                scenario.onActivity(a->{View root=a.getWindow().getDecorView();assertEquals(ActivityInfo.SCREEN_ORIENTATION_FULL_SENSOR,a.getRequestedOrientation());assertNull(DeviceSupport.tag(root,"theme-brand"));View viewport=DeviceSupport.tag(root,"box-camera-viewport");assertEquals(0,viewport.getTop());assertEquals(((View)viewport.getParent()).getHeight(),viewport.getHeight());VerticalZoom zoom=(VerticalZoom)DeviceSupport.tag(root,"vertical-zoom");assertEquals(viewport.getHeight()/2f,(zoom.getTop()+zoom.getBottom())/2f,2);VerticalZoom synthetic=new VerticalZoom(a);synthetic.setup(1,3,1,Locale.ENGLISH,synthetic::value);synthetic.performAccessibilityAction(android.view.accessibility.AccessibilityNodeInfo.ACTION_SCROLL_FORWARD,null);assertEquals(2f,(Float)DeviceSupport.get(synthetic,"value"),.001f);if(android.animation.ValueAnimator.areAnimatorsEnabled()){assertNotNull(DeviceSupport.get(synthetic,"motion"));assertNotNull(DeviceSupport.get(synthetic,"effect"));}assertTrue(a.session.tracker.items().isEmpty());});DeviceSupport.shot(null,"build3-theme-camera-"+theme);
                if(theme.equals("translumina")){scenario.onActivity(a->a.session.tracker.importCode(new ScanTracker.Detection("orientation-test-fixture","QR",.1f,.1f,.2f,.2f),0));device.unfreezeRotation();device.executeShellCommand("touch /data/local/tmp/bmd-rotate-landscape");long rotatedDeadline=SystemClock.elapsedRealtime()+20000;AtomicBoolean rotated=new AtomicBoolean();while(SystemClock.elapsedRealtime()<rotatedDeadline){scenario.onActivity(a->rotated.set(a.getResources().getConfiguration().orientation==Configuration.ORIENTATION_LANDSCAPE&&(Boolean)DeviceSupport.get(a,"ready")));if(rotated.get())break;SystemClock.sleep(150);}scenario.onActivity(a->android.util.Log.i("BMD-rotate","orientation="+a.getResources().getConfiguration().orientation+" ready="+DeviceSupport.get(a,"ready")+" inCamera="+DeviceSupport.get(a,"inCamera")+" requested="+a.getRequestedOrientation()+" rotation="+device.getDisplayRotation()));DeviceSupport.shot(null,"build3-rotation-check");assertTrue("Rotated camera must rebind",rotated.get());InstrumentationRegistry.getInstrumentation().waitForIdleSync();scenario.onActivity(a->{assertEquals(13,a.session.expected);assertEquals(1,a.session.tracker.items().size());assertEquals("orientation-test-fixture",a.session.tracker.items().get(0).raw);assertNotNull(DeviceSupport.tag(a.getWindow().getDecorView(),"box-camera-viewport"));View zoom=DeviceSupport.tag(a.getWindow().getDecorView(),"vertical-zoom"),gallery=DeviceSupport.tag(a.getWindow().getDecorView(),"gallery-scan");assertTrue("Landscape zoom must clear gallery control",zoom.getBottom()<gallery.getTop());});DeviceSupport.shot(null,"build3-theme-camera-landscape");scenario.onActivity(a->a.summary());long menuDeadline=SystemClock.elapsedRealtime()+10000;AtomicBoolean portrait=new AtomicBoolean();while(SystemClock.elapsedRealtime()<menuDeadline){scenario.onActivity(a->portrait.set(a.getResources().getConfiguration().orientation==Configuration.ORIENTATION_PORTRAIT));if(portrait.get())break;SystemClock.sleep(150);}assertTrue("Menu must stay portrait with device held sideways",portrait.get());device.executeShellCommand("touch /data/local/tmp/bmd-rotate-portrait");SystemClock.sleep(1500);device.unfreezeRotation();}
                scenario.onActivity(a->{a.summary();assertEquals(ActivityInfo.SCREEN_ORIENTATION_PORTRAIT,a.getRequestedOrientation());assertEquals(13,a.session.expected);});
            }
        }
    }
}

